//! The secrets detectors on a made-up corpus: how many of the listed ways
//! to write a password into a command they find, how many credentials of
//! the formats they know, and how many clean lines they flag.
//!
//! Every secret here is generated by this file from a fixed seed; none was
//! ever issued by a service, and nothing is taken from a real repository.
//! The numbers say how well the detectors cover the shapes listed below.
//! They are not a recall measured on real leaks: a shape nobody listed is
//! not counted.
//!
//! `MEMPROVE_SECRETS_CORPUS_DIR=<dir> cargo test -p memprove-policy --test
//! secrets_corpus` also writes the corpus files and a manifest there, for
//! running another scanner on the same input.

use std::{collections::BTreeMap, fmt::Write as _, fs, path::Path};

use memprove_policy::{json, scan};

/// Variants of each shape.
const VARIANTS: usize = 20;

struct Rng(u64);

impl Rng {
    fn next(&mut self) -> u64 {
        self.0 ^= self.0 << 13;
        self.0 ^= self.0 >> 7;
        self.0 ^= self.0 << 17;
        self.0
    }

    fn below(&mut self, limit: usize) -> usize {
        usize::try_from(self.next() % u64::try_from(limit).unwrap()).unwrap()
    }

    fn of(&mut self, alphabet: &str) -> char {
        let chars: Vec<char> = alphabet.chars().collect();
        chars[self.below(chars.len())]
    }

    fn run(&mut self, alphabet: &str, length: usize) -> String {
        (0..length).map(|_| self.of(alphabet)).collect()
    }
}

const LOWER: &str = "abcdefghijkmnopqrstuvwxyz";
const UPPER: &str = "ABCDEFGHJKLMNPQRSTUVWXYZ";
const DIGIT: &str = "23456789";
const ALNUM: &str = "abcdefghijkmnopqrstuvwxyzABCDEFGHJKLMNPQRSTUVWXYZ23456789";
const HEX: &str = "0123456789abcdef";

/// A password a person might choose: 8 to 16 letters, digits and `-_.`.
fn plain(rng: &mut Rng) -> String {
    let length = 8 + rng.below(9);
    let mut value = String::new();
    value.push(rng.of(LOWER));
    value.push(rng.of(UPPER));
    value.push(rng.of(DIGIT));
    let alphabet = format!("{ALNUM}-_.");
    value.push_str(&rng.run(&alphabet, length - 4));
    value.push(rng.of(ALNUM));
    value
}

/// A password with punctuation, for places that quote it.
fn rich(rng: &mut Rng) -> String {
    let mut value = plain(rng);
    let at = 1 + rng.below(value.len() - 2);
    value.insert(at, rng.of("!#%^+,"));
    value
}

/// A generated token: 32 to 48 letters and digits.
fn token(rng: &mut Rng) -> String {
    let length = 32 + rng.below(17);
    let mut value = String::new();
    value.push(rng.of(LOWER));
    value.push(rng.of(UPPER));
    value.push(rng.of(DIGIT));
    value.push_str(&rng.run(ALNUM, length - 3));
    value
}

